//! Colours and widget styling: a dark and a light palette sharing one indigo accent.

use eframe::egui::{self, Color32, CornerRadius, Stroke, Visuals};

#[derive(Clone, Copy)]
pub struct Pal {
    pub dark: bool,
    pub bg: Color32,
    pub panel: Color32,
    pub raised: Color32,
    pub text: Color32,
    pub dim: Color32,
    pub accent: Color32,
    pub on_accent: Color32,
    pub sel: Color32,
    pub hover: Color32,
    pub line: Color32,
}

pub fn pal(dark: bool) -> Pal {
    if dark {
        Pal {
            dark,
            bg: Color32::from_rgb(19, 20, 25),
            panel: Color32::from_rgb(26, 28, 35),
            raised: Color32::from_rgb(36, 39, 49),
            text: Color32::from_rgb(228, 231, 240),
            dim: Color32::from_rgb(137, 144, 163),
            accent: Color32::from_rgb(129, 140, 248),
            on_accent: Color32::from_rgb(15, 16, 28),
            sel: Color32::from_rgba_unmultiplied(129, 140, 248, 62),
            hover: Color32::from_rgb(40, 43, 55),
            line: Color32::from_rgb(40, 43, 54),
        }
    } else {
        Pal {
            dark,
            bg: Color32::from_rgb(244, 245, 249),
            panel: Color32::from_rgb(255, 255, 255),
            raised: Color32::from_rgb(242, 243, 248),
            text: Color32::from_rgb(28, 30, 40),
            dim: Color32::from_rgb(112, 118, 136),
            accent: Color32::from_rgb(79, 70, 229),
            on_accent: Color32::WHITE,
            sel: Color32::from_rgba_unmultiplied(79, 70, 229, 38),
            hover: Color32::from_rgb(240, 241, 248),
            line: Color32::from_rgb(232, 234, 241),
        }
    }
}

pub fn apply(ctx: &egui::Context, dark: bool) {
    let p = pal(dark);
    let mut v = if dark { Visuals::dark() } else { Visuals::light() };
    v.panel_fill = p.panel;
    v.window_fill = p.panel;
    v.extreme_bg_color = p.raised;
    v.faint_bg_color = p.raised;
    v.window_stroke = Stroke::new(1.0_f32, p.line);
    v.selection.bg_fill = p.sel;
    v.selection.stroke = Stroke::new(1.0_f32, p.accent);
    v.hyperlink_color = p.accent;
    v.window_corner_radius = CornerRadius::same(12);
    v.menu_corner_radius = CornerRadius::same(8);
    let r = CornerRadius::same(8);
    let w = &mut v.widgets;
    for s in [&mut w.noninteractive, &mut w.inactive, &mut w.hovered, &mut w.active, &mut w.open] {
        s.corner_radius = r;
        s.fg_stroke = Stroke::new(1.0_f32, p.text);
    }
    w.noninteractive.bg_stroke = Stroke::new(1.0_f32, p.line);
    w.inactive.weak_bg_fill = p.raised;
    w.inactive.bg_fill = p.raised;
    w.inactive.bg_stroke = Stroke::NONE;
    w.hovered.weak_bg_fill = p.hover;
    w.hovered.bg_fill = p.hover;
    w.hovered.bg_stroke = Stroke::new(1.0_f32, p.line);
    w.active.weak_bg_fill = p.sel;
    w.active.bg_fill = p.sel;
    w.open.weak_bg_fill = p.hover;
    w.open.bg_fill = p.hover;
    ctx.set_visuals(v);
    ctx.data_mut(|d| d.insert_temp(egui::Id::new("quickfind-pal"), p));
}

pub fn get(ctx: &egui::Context) -> Pal {
    ctx.data(|d| d.get_temp(egui::Id::new("quickfind-pal"))).unwrap_or_else(|| pal(true))
}

