//! File actions: open with, properties, recycle bin delete, rename.

#[cfg(windows)]
fn wide(s: &str) -> Vec<u16> {
    s.encode_utf16().chain([0]).collect()
}

/// "Open with..." chooser.
pub fn open_with(path: &str) {
    #[cfg(windows)]
    {
        use windows_sys::Win32::UI::Shell::ShellExecuteW;
        use windows_sys::Win32::UI::WindowsAndMessaging::SW_SHOWNORMAL;
        let (verb, file) = (wide("openas"), wide(path));
        unsafe {
            ShellExecuteW(std::ptr::null_mut(), verb.as_ptr(), file.as_ptr(), std::ptr::null(), std::ptr::null(), SW_SHOWNORMAL);
        }
    }
    #[cfg(not(windows))]
    let _ = path;
}

/// The system Properties window.
pub fn properties(path: &str) {
    #[cfg(windows)]
    {
        use windows_sys::Win32::UI::Shell::{ShellExecuteExW, SEE_MASK_INVOKEIDLIST, SHELLEXECUTEINFOW};
        use windows_sys::Win32::UI::WindowsAndMessaging::SW_SHOW;
        let (verb, file) = (wide("properties"), wide(path));
        let mut info: SHELLEXECUTEINFOW = unsafe { std::mem::zeroed() };
        info.cbSize = std::mem::size_of::<SHELLEXECUTEINFOW>() as u32;
        info.fMask = SEE_MASK_INVOKEIDLIST as _;
        info.lpVerb = verb.as_ptr();
        info.lpFile = file.as_ptr();
        info.nShow = SW_SHOW as _;
        unsafe {
            ShellExecuteExW(&mut info);
        }
    }
    #[cfg(not(windows))]
    let _ = path;
}

/// Move files and folders to the Recycle Bin.
pub fn recycle(paths: &[String]) -> Result<(), String> {
    #[cfg(windows)]
    {
        use windows_sys::Win32::UI::Shell::{
            SHFileOperationW, FOF_ALLOWUNDO, FOF_NOCONFIRMATION, FOF_NOERRORUI, FOF_SILENT, FO_DELETE, SHFILEOPSTRUCTW,
        };
        let mut from: Vec<u16> = Vec::new();
        for p in paths {
            from.extend(p.encode_utf16());
            from.push(0);
        }
        from.push(0);
        let mut op: SHFILEOPSTRUCTW = unsafe { std::mem::zeroed() };
        op.wFunc = FO_DELETE as _;
        op.pFrom = from.as_ptr();
        op.fFlags = (FOF_ALLOWUNDO | FOF_NOCONFIRMATION | FOF_NOERRORUI | FOF_SILENT) as _;
        let rc = unsafe { SHFileOperationW(&mut op) };
        if rc != 0 {
            return Err(format!("Delete failed (code {rc})"));
        }
        Ok(())
    }
    #[cfg(not(windows))]
    {
        let _ = paths;
        Err("Recycle Bin is only available on Windows".into())
    }
}

/// Rename a file or folder in place.
pub fn rename(path: &str, new_name: &str) -> Result<(), String> {
    let new_name = new_name.trim();
    if new_name.is_empty() || new_name.contains(['\\', '/', ':', '*', '?', '"', '<', '>', '|']) {
        return Err("That name is not allowed".into());
    }
    let p = std::path::Path::new(path);
    let Some(parent) = p.parent() else { return Err("Cannot rename a drive".into()) };
    std::fs::rename(p, parent.join(new_name)).map_err(|e| format!("Rename failed: {e}"))
}

//! What the preview pane shows for one selected file or folder.

use crate::dates::format_filetime;
use crate::filters::{kind_of, Kind};
use crate::index::Index;
use crate::platform::{attrib_text, human_size};
use std::io::Read;

pub enum Body {
    Image(String),
    Text(String),
    Note(String),
}

pub struct Preview {
    pub id: u32,
    pub path: String,
    pub name: String,
    pub kind_label: String,
    pub rows: Vec<(&'static str, String)>,
    pub body: Body,
}

const IMAGE_EXTS: [&str; 6] = ["png", "jpg", "jpeg", "gif", "bmp", "webp"];
const MAX_IMAGE: u64 = 30 * 1024 * 1024;

pub fn build(idx: &Index, id: u32) -> Option<Preview> {
    let e = idx.entries.get(id as usize)?;
    let path = idx.full_path(e);
    let ext = idx.extension(e).to_lowercase();
    let is_dir = e.is_dir();
    let kind_label = if is_dir {
        "Folder".to_string()
    } else if ext.is_empty() {
        "File".to_string()
    } else {
        format!("{} file", ext.to_uppercase())
    };
    let mut rows = Vec::new();
    if is_dir {
        rows.push(("Contains", format!("{} items", e.children)));
    } else {
        rows.push(("Size", format!("{}  ({} bytes)", human_size(e.size), crate::platform::thousands(e.size))));
    }
    rows.push(("Modified", format_filetime(e.mtime)));
    rows.push(("Created", format_filetime(e.ctime)));
    rows.push(("Location", idx.dir_path(e).to_string()));
    let attrs = attrib_text(e.attrs);
    if !attrs.is_empty() {
        rows.push(("Attributes", attrs));
    }
    let body = if is_dir {
        Body::Note("Folder".into())
    } else if IMAGE_EXTS.contains(&ext.as_str()) {
        if e.size <= MAX_IMAGE {
            Body::Image(format!("file://{path}"))
        } else {
            Body::Note("Picture is too large to preview".into())
        }
    } else if matches!(kind_of(&ext), Kind::Audio | Kind::Video | Kind::Archive | Kind::Exe) {
        Body::Note("No preview for this kind of file".into())
    } else {
        match sniff_text(&path) {
            Some(t) => Body::Text(t),
            None => Body::Note("No preview for this kind of file".into()),
        }
    };
    Some(Preview { id, name: idx.name(e).to_string(), path, kind_label, rows, body })
}

/// The start of a text file, or None when it looks binary.
fn sniff_text(path: &str) -> Option<String> {
    let mut f = std::fs::File::open(path).ok()?;
    let mut buf = vec![0u8; 6000];
    let n = f.read(&mut buf).ok()?;
    buf.truncate(n);
    if buf.contains(&0) {
        return None;
    }
    let s = String::from_utf8_lossy(&buf).into_owned();
    let total = s.chars().count();
    let bad = s.chars().filter(|c| *c == '\u{FFFD}').count();
    if total > 0 && bad * 20 > total {
        return None;
    }
    let mut out: String = s.lines().take(60).collect::<Vec<_>>().join("\n");
    if out.chars().count() > 2500 {
        out = out.chars().take(2500).collect();
    }
    Some(out)
}

